usage:
import { HeroMarqueeScreens } from "@/components/design-for-ai/hero-marquee-screens";

// Pass your own screens: each one is a title, a meta note and a body you draw in markup
// on a 320 × 176 canvas (the row scales it). Omit `screens` for the built-in freight desk.
<HeroMarqueeScreens
  headline="Run freight like a team of fifty."
  primary={{ label: "Start a free trial", href: "/signup" }}
  secondary={{ label: "Book a 20-minute demo", href: "/demo" }}
  rows={3}
  speed={22}
  tilt={false}
  align="center"
  accent="#ff5a1f"
  theme="dark"
/>
